const crypto = require('crypto');
require('dotenv').config();

// Use a persistent secret from ENV or generate a random one on startup

const { getNewPage } = require("../utils/browserManager");

async function extractStreamFromPage(contentType, contentId, seasonNum, episodeNum) {
    let vixsrcUrl;
    let subtitleApiUrl;

    if (contentType === 'movie') {
        vixsrcUrl = `${BASE_URL}/movie/${contentId}`;
        subtitleApiUrl = `https://sub.wyzie.ru/search?id=${contentId}`;
    } else {
        vixsrcUrl = `${BASE_URL}/tv/${contentId}/${seasonNum}/${episodeNum}`;
        subtitleApiUrl = `https://sub.wyzie.ru/search?id=${contentId}&season=${seasonNum}&episode=${episodeNum}`;
    }

    console.log(`[Vixsrc] Fetching (Browser): ${vixsrcUrl}`);
    let page;

    try {
        page = await getNewPage();
        // Block heavy resources to speed up
        await page.route('**/*', route => {
            const type = route.request().resourceType();
            if (['image', 'font', 'stylesheet'].includes(type)) return route.abort();
            route.continue();
        });

        await page.goto(vixsrcUrl, { waitUntil: 'domcontentloaded', timeout: 25000 });

        // Extract masterPlaylist from window object
        const playlistData = await page.evaluate(() => {
            if (window.masterPlaylist) {
                return window.masterPlaylist;
            }
            return null;
        });

        if (playlistData && playlistData.url && playlistData.params) {
            const { url, params } = playlistData;
            const token = params.token;
            const expires = params.expires;
            const masterPlaylistUrl = url.includes('?') 
                ? `${url}&token=${token}&expires=${expires}&h=1&lang=en` 
                : `${url}?token=${token}&expires=${expires}&h=1&lang=en`;

            return { masterPlaylistUrl, subtitleApiUrl, vixsrcUrl };
        }

        return { masterPlaylistUrl: null, subtitleApiUrl, vixsrcUrl };

    } catch (e) {
        console.error(`[Vixsrc] Browser extraction failed: ${e.message}`);
