// Segment & File Proxy (TS, MP4, keys, etc.)
app.get('/ts-proxy', cors(), async (req, res) => {
    let { url: targetUrl, token } = req.query;
    let decryptedHeaders = null;

    if (token) {
        const decrypted = decryptUrl(token, req.ip);
        if (!decrypted) return res.status(403).json({ error: 'Invalid or expired token' });
        targetUrl = decrypted.url;
        decryptedHeaders = decrypted.headers;
    } else if (!targetUrl) {
        return res.status(400).json({ error: 'Token or URL parameter is required' });
    }

    const headers = { ...(decryptedHeaders || {}) };
    // IMPORTANT: Pass client's Range header for seeking.
    if (req.headers.range) {
        headers.range = req.headers.range;
    }

    try {
        const upstreamRes = await fetchWithRetry(targetUrl, { headers });

        res.status(upstreamRes.status);

        // Critical for seeking: copy all relevant headers from upstream
        ['content-length', 'content-range', 'accept-ranges', 'last-modified', 'etag', 'cache-control'].forEach(headerName => {
            const headerValue = upstreamRes.headers.get(headerName);
            if (headerValue) res.setHeader(headerName, headerValue);
        });

        // Force correct Content-Type for VLC if upstream is vague
        let contentType = upstreamRes.headers.get('content-type');
        if (!contentType || contentType === 'application/octet-stream' || contentType === 'text/plain') {
            contentType = 'video/mp4';
        }
        res.setHeader('Content-Type', contentType);

        res.setHeader('Access-Control-Allow-Origin', '*');

        upstreamRes.body.pipe(res);
    } catch (error) {
        console.error(`[ts-proxy] Failure for ${targetUrl}:`, error);
        if (!res.headersSent) {
            res.status(502).json({ error: 'Proxy failed', message: error.message });
        }
    }
});

