const axios = require('axios');
const cheerio = require('cheerio');

async function testStreamedScraper() {
    const watchUrl = 'https://streamed.pk/watch/neptunas-vs-hapoel-jerusalem/echo/1';
    console.log(`Testing: ${watchUrl}`);

    try {
        // 1. Get Watch Page
        const response = await axios.get(watchUrl, {
            headers: {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
            }
        });
        const html = response.data;
        console.log('Watch Page Fetched.');

        // 2. Extract API details (Looking for match ID)
        // Pattern: https://streamed.pk/api/stream/echo/neptunas-vs-hapoel-jerusalem-basketball-453243
        // It might be in script tags.
        const apiMatch = html.match(/\/api\/stream\/[^"']+/);
        if (apiMatch) {
            console.log(`Found API URL in HTML: ${apiMatch[0]}`);
            const apiUrl = `https://streamed.pk${apiMatch[0]}`;

            // 3. Call API
            const apiResponse = await axios.get(apiUrl, {
                headers: {
                    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                    'Referer': watchUrl
                }
            });
            console.log('API Response:', JSON.stringify(apiResponse.data, null, 2));

            // 4. Get Embed
            const streams = apiResponse.data;
            if (streams && streams.length > 0) {
                const embedUrl = streams[0].embedUrl;
                console.log(`Embed URL: ${embedUrl}`);

                // 5. Scrape Embed
                const embedResponse = await axios.get(embedUrl, {
                    headers: {
                        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                        'Referer': 'https://streamed.pk/' 
                    }
                });

                // 6. Extract M3U8
                const embedHtml = embedResponse.data;
                const m3u8Match = embedHtml.match(/(https?:\/\/[^"']+\.m3u8[^"']*)/);
                if (m3u8Match) {
                    console.log(`SUCCESS! M3U8 Found: ${m3u8Match[1]}`);
                } else {
                    console.log('No M3U8 found in embed.');
                    // console.log(embedHtml); // Debug if needed
                }
            }

        } else {
            console.log('No API URL found in HTML.');
        }

    } catch (e) {
        console.error('Error:', e.message);
    }
}

testStreamedScraper();

