async extractAllStreams(watchUrl) {
    try {
        console.log(`[Extractor] Scraping: ${watchUrl}`);

        // 1. Fetch Watch Page
        const response = await this.client.get(watchUrl);
        const html = response.data;

        // 2. Parse Data
        // We search for the "sources" array directly in the HTML, as it's the critical piece.
        // Pattern: sources:[{...}]
        const sourcesMatch = html.match(/sources:(\[\{.+?\}\])(?:,|,\}|, \}| \})/);

        if (!sourcesMatch) {
            // Try alternate pattern with quotes
            const quotedSourcesMatch = html.match(/"sources":(\[\{.+?\}\])/);
            if (!quotedSourcesMatch) {
                throw new Error('Could not find sources list in page');
            }
            return await this.processSources(JSON.parse(quotedSourcesMatch[1]), 'Unknown', 'sports');
        }

        // Clean up the JS object string to make it valid JSON
        // The keys might be unquoted (source: "alpha")
        let sourcesStr = sourcesMatch[1];

        // Basic attempt to quote keys: {key: -> {"key":
        // But values might contain : so be careful. 
        // Luckily the structure seems simple: {source:"...",id:"..."}
        // We can try to use eval or Function (unsafe but effective for scraping) or regex-replace.
        // Since we are in Node, strictly avoiding eval is best.
        // Let's use regex to quote keys.
        sourcesStr = sourcesStr.replace(/([{,])\s*([a-zA-Z0-9_]+):/g, '$1"$2":');

        let sources;
        try {
            sources = JSON.parse(sourcesStr);
        } catch (e) {
            console.log(`[Extractor] JSON fix failed: ${e.message}. Raw: ${sourcesStr}`);
            // Fallback: simple regex extraction of source/id pairs
            sources = [];
            const sourceItemRegex = /source:"([^"]+)",id:"([^"]+)"/g;
            let m;
            while ((m = sourceItemRegex.exec(sourcesMatch[1])) !== null) {
                sources.push({ source: m[1], id: m[2] });
            }
            // Handle reversed order {id:..., source:...}
            const sourceItemRegexRev = /id:"([^"]+)",source:"([^"]+)"/g;
            while ((m = sourceItemRegexRev.exec(sourcesMatch[1])) !== null) {
                sources.push({ id: m[1], source: m[2] });
            }
        }

        if (!sources || sources.length === 0) {
            throw new Error('No sources parsed');
        }

        // Extract Title and Category
        const titleMatch = html.match(/title:"([^"]+)"/);
        const title = titleMatch ? titleMatch[1] : 'Unknown Match';

        const categoryMatch = html.match(/category:"([^"]+)"/);
        const category = categoryMatch ? categoryMatch[1] : 'sports';

        return await this.processSources(sources, title, category);

    } catch (error) {
        console.error(`[Extractor] Fatal error: ${error.message}`);
        return { error: error.message };
    }
}

