const axios = require('axios');
const cheerio = require('cheerio');
const { getNewPage } = require('./utils/browserManager');

class LivesportM3U8Extractor {
    constructor() {
        this.client = axios.create({
            headers: {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
                'Accept-Language': 'en-US,en;q=0.5',
                'Connection': 'keep-alive'
            },
            timeout: 10000
        });
    }

    // ... extractAllStreams and processSources remain the same ...

    async extractM3U8FromEmbed(embedUrl) {
        let page = null;
        try {
            // console.log(`[Extractor] Browser scraping: ${embedUrl}`);
            page = await getNewPage();

            // Set up request interception
            let m3u8Url = null;
            await page.route('**/*', route => {
                const url = route.request().url();
                if (url.includes('.m3u8') && !m3u8Url) {
                    m3u8Url = url;
                    // console.log(`[Extractor] Intercepted M3U8: ${url}`);
                }

                // Block ads/images to speed up
                const type = route.request().resourceType();
                if (['image', 'font', 'stylesheet', 'media'].includes(type) && !url.includes('.m3u8')) {
                    return route.abort();
                }
                route.continue();
            });

            await page.setExtraHTTPHeaders({
                'Referer': 'https://streamed.pk/'
            });

            await page.goto(embedUrl, { waitUntil: 'domcontentloaded', timeout: 15000 });

            // Wait a bit for the player to init and request the stream
            const start = Date.now();
            while (!m3u8Url && Date.now() - start < 5000) {
                await new Promise(r => setTimeout(r, 200));
            }

            return m3u8Url;

        } catch (e) {
            // console.log(`[Extractor] Browser scrape failed: ${e.message}`);
            return null;
        } finally {
            if (page) await page.close();
        }
    }
}

