            // Pattern: sources:[{...}] or "sources":[{...}]
            // We use non-greedy matching to stop at the first closing bracket.
            const sourcesMatch = html.match(/(?:sources|"sources"):\s*(\[.*?\])/);

            if (!sourcesMatch) {
                throw new Error('Could not find sources list in page');
            }

            let sourcesStr = sourcesMatch[1];
            let sources = [];

            try {
                // Try parsing directly (if it's valid JSON)
                sources = JSON.parse(sourcesStr);
            } catch (e) {
                // If it fails, try to fix unquoted keys
                try {
                    const fixedStr = sourcesStr.replace(/([{,])\s*([a-zA-Z0-9_]+):/g, '$1"$2":');
                    sources = JSON.parse(fixedStr);
                } catch (e2) {
                    console.log(`[Extractor] JSON parse failed: ${e2.message}. Using regex fallback.`);

