                    // Match objects inside the array
                    const objectRegex = /\{.*?\}/g;
                    let objMatch;

                    while ((objMatch = objectRegex.exec(sourcesStr)) !== null) {
                        const objStr = objMatch[0];
                        const sourceMatch = objStr.match(/(?:source|"source"):\s*"([^"]+)"/);
                        const idMatch = objStr.match(/(?:id|"id"):\s*"([^"]+)"/);

                        if (sourceMatch && idMatch) {
                            sources.push({ source: sourceMatch[1], id: idMatch[1] });
                        }
                    }
                }
            }

            if (!sources || sources.length === 0) {
                throw new Error(`No sources parsed from: ${sourcesStr.substring(0, 50)}...`);
            }

            // Extract Title and Category
            const titleMatch = html.match(/title:"([^"]+)"/);
            const title = titleMatch ? titleMatch[1] : 'Unknown Match';

            const categoryMatch = html.match(/category:"([^"]+)"/);
            const category = categoryMatch ? categoryMatch[1] : 'sports';

