async extractM3U8FromEmbed(embedUrl) {
    let page = null;
    try {
        console.log(`[Extractor] Browser scraping: ${embedUrl}`);
        page = await getNewPage();

        let m3u8Url = null;

        // 1. Network Interception
        await page.route('**/*', route => {
            const url = route.request().url();
            if ((url.includes('.m3u8') || url.includes('playlist')) && !m3u8Url) {
                console.log(`[Extractor] Intercepted M3U8: ${url}`);
                m3u8Url = url;
            }

            const type = route.request().resourceType();
            // Allow scripts/xhr as they drive the player
            if (['image', 'font', 'stylesheet', 'media'].includes(type) && !url.includes('.m3u8')) {
                return route.abort();
            }
            route.continue();
        });

        await page.setExtraHTTPHeaders({
            'Referer': 'https://streamed.pk/'
        });

        await page.goto(embedUrl, { waitUntil: 'networkidle', timeout: 20000 });

        // 2. Interaction (Click center to play)
        try {
            await page.mouse.click(300, 300); // Blind click in center
            await page.evaluate(() => {
                // Try generic play buttons
                const btn = document.querySelector('.jw-icon-playback') || document.querySelector('button[aria-label="Play"]');
                if (btn) btn.click();
            });
        } catch (e) {}

        // 3. Wait loop for network request
        const start = Date.now();
        while (!m3u8Url && Date.now() - start < 10000) {
            await new Promise(r => setTimeout(r, 500));
        }

        // 4. Fallback: JWPlayer extraction
        if (!m3u8Url) {
            console.log('[Extractor] Network intercept failed, trying JWPlayer instance...');
            try {
                const jwConfig = await page.evaluate(() => {
                    if (window.jwplayer) {
                        // Try to get first player
                        const players = window.jwplayer();
                        if (players && players.getConfig) {
                            return players.getConfig().file;
                        }
                        // Iterate if multiple
                        for (let i = 0; i < 5; i++) {
                            const p = window.jwplayer(i);
                            if (p && p.getConfig) return p.getConfig().file;
                        }
                    }
                    return null;
                });
                if (jwConfig) {
                    console.log(`[Extractor] Found via JWPlayer config: ${jwConfig}`);
                    m3u8Url = jwConfig;
                }
            } catch (e) {
                console.log(`[Extractor] JWPlayer check failed: ${e.message}`);
            }
        }

        return m3u8Url;

    } catch (e) {
        console.log(`[Extractor] Browser scrape failed: ${e.message}`);
        return null;
    } finally {
        if (page) await page.close();
    }
}

