const axios = require('axios');
const fs = require('fs').promises;

async function scrapeAlbum(albumId) {
    const url = `https://www.hitv.vip/share/album/${albumId}`;
    console.log(`Scraping Album: ${url}`);

    try {
        const response = await axios.get(url, {
            headers: {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                'Accept-Language': 'en-US,en;q=0.9'
            }
        });

        const html = response.data;

        // Extract window.__NUXT__ block
        // Pattern: window.__NUXT__=(function(a,b,c...){...}(...));
        const nuxtMatch = html.match(/window\.__NUXT__=\(function\((.*?)\)\{([\s\S]*?)\}\((.*?)\)\);/);

        if (!nuxtMatch) {
            console.error('Could not find __NUXT__ data');
            return null;
        }

        const argsNames = nuxtMatch[1].split(',');
        const argsValuesStr = nuxtMatch[3];

        // Parsing the arguments values is tricky because they are a comma-separated list of literals (strings, numbers, null, etc.)
        // We can use a simple trick: wrap them in [] and JSON.parse if possible, or use a more robust split.
        // Since they are literals, we can try to evaluate them safely or use a parser.

        // For now, let's use a simpler regex approach to find sid/name pairs in the whole HTML
        // as the Nuxt parsing is very complex.

        const dramas = [];
        const seenIds = new Set();

        // Patterns seen in the dump:
        // sid:"s_...",sidAlias:"...",name:"..."
        // Or unquoted keys in the function call

        // Let's look for "sid":"s_..." or sid:"s_..."
        const sidRegex = /(?:"sid"|sid):"(s_[a-zA-Z0-9_]+)"/g;
        const nameRegex = /(?:"name"|name):"([^"]+)"/;

        // Find all SIDs
        let m;
        while ((m = sidRegex.exec(html)) !== null) {
            const sid = m[1];
            if (seenIds.has(sid)) continue;
            seenIds.add(sid);

            // Search for name around this SID (context search)
            const context = html.substring(m.index, m.index + 500);
            const nameMatch = context.match(nameRegex);
            const name = nameMatch ? nameMatch[1] : 'Unknown';

            dramas.push({ sid, name });
        }

        console.log(`Found ${dramas.length} dramas in album.`);
        return dramas;

    } catch (e) {
        console.error(`Scrape failed: ${e.message}`);
        return null;
    }
}

async function main() {
    const albumId = 'a_MT4IPBbd_619kbg8HYh1g';
    const dramas = await scrapeAlbum(albumId);
    if (dramas) {
        await fs.writeFile('hitv_album_dramas.json', JSON.stringify(dramas, null, 2));
        console.log('Saved to hitv_album_dramas.json');
    }
}

main();

