#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

console.log('[setup] Checking for browser installation...');

// Check if Chrome/Chromium exists in common locations
const browserPaths = [
  '/usr/bin/google-chrome',
  '/usr/bin/chromium-browser',
  '/usr/bin/chromium',
  '/opt/google/chrome/chrome',
  '/usr/local/bin/chrome',
  '/usr/local/bin/chromium',
  '/home/chrome/chrome',
  '/var/www/chrome/chrome'
];

let browserExists = false;
for (const browserPath of browserPaths) {
  if (fs.existsSync(browserPath)) {
    console.log(`[setup] Browser found at: ${browserPath}`);
    browserExists = true;
    // Set environment variable if not already set
    if (!process.env.BROWSER_EXECUTABLE_PATH && !process.env.PUPPETEER_EXECUTABLE_PATH) {
        process.env.BROWSER_EXECUTABLE_PATH = browserPath;
    }
    break;
  }
}

if (!browserExists) {
  console.log('[setup] Chrome/Chromium not found in standard paths');
  console.log('[setup] You may need to:');
  console.log('[setup] 1. Install Chromium via your package manager (e.g., apt-get install chromium-browser)');
  console.log('[setup] 2. Run "npx playwright install chromium" if you have write access');
  console.log('[setup] 3. Use providers that don\'t require browser automation');

  // Don't exit with error, just warn and continue
  console.log('[setup] Continuing startup - automation providers may fail without a browser');
} else {
  console.log('[setup] Browser is available');
}

console.log('[setup] Starting application...');

const { chromium, firefox } = require("playwright-extra");
const StealthPlugin = require("puppeteer-extra-plugin-stealth");
const { buildLaunchOptions } = require("./browserConfig");

// Use stealth plugin for Chromium only
chromium.use(StealthPlugin());

let browserInstance = null;
let firefoxInstance = null;
let launchMutex = Promise.resolve();

// Semaphore for concurrency control
const MAX_GLOBAL_CONCURRENT_PAGES = process.env.MAX_CONCURRENT_PAGES ? parseInt(process.env.MAX_CONCURRENT_PAGES) : 5;
const queue = [];
let activePages = 0;

async function acquirePageSlot() {
    if (activePages < MAX_GLOBAL_CONCURRENT_PAGES) {
        activePages++;
        return;
    }
    await new Promise(resolve => queue.push(resolve));
    activePages++;
}

function releasePageSlot() {
    activePages--;
    if (queue.length > 0) {
        const next = queue.shift();
        next();
    }
}

async function getBrowser(type = 'chromium') {
    // Lock the launch process so only one browser spawns at a time
    return new Promise((resolve, reject) => {
        launchMutex = launchMutex.then(async () => {
            try {
                const browser = await _getBrowserInternal(type);
                resolve(browser);
            } catch (e) {
                reject(e);
            }
        });
    });
}

async function _getBrowserInternal(type = 'chromium') {
    const headless = process.env.BROWSER_HEADLESS !== 'false';

    if (type === 'firefox') {
        if (!firefoxInstance) {
            console.log(`[BrowserManager] Launching Firefox (Headless: ${headless})...`);
            firefoxInstance = await firefox.launch({ headless });
            firefoxInstance.on('disconnected', () => { firefoxInstance = null; });
        }
        return firefoxInstance;
    }

    if (!browserInstance) {
        console.log(`[BrowserManager] Launching CPU-optimized Chromium (Headless: ${headless})...`);
        const baseOptions = buildLaunchOptions();
        // Force headless based on env if not already set in baseOptions
        if (baseOptions.headless === undefined) {
            baseOptions.headless = headless;
        }

        const extraArgs = [
            '--disable-canvas-aa',
            '--disable-2d-canvas-clip-aa',
            '--disable-gl-drawing-for-tests',
            '--disable-dev-shm-usage',
            '--no-zygote',
            '--use-gl=swiftshader',
            '--disable-software-rasterizer',
            '--mute-audio',
            '--disable-extensions',
            '--disable-background-networking',
            '--disable-background-timer-throttling',
            '--disable-backgrounding-occluded-windows',
            '--disable-breakpad',
            '--disable-component-extensions-with-background-pages',
            '--disable-ipc-flooding-protection',
            '--disable-renderer-backgrounding',
            '--disable-notifications',
            '--disable-popup-blocking',
            '--no-first-run',
            '--no-default-browser-check'
        ];
        const mergedArgs = Array.from(new Set([...(baseOptions.args || []), ...extraArgs]));
        browserInstance = await chromium.launch({ ...baseOptions, args: mergedArgs });
        browserInstance.on('disconnected', () => { browserInstance = null; });
    }
    return browserInstance;
}

async function getNewPage(options = {}) {
    const browserType = options.browserType || 'chromium';

    // Acquire lock before launching context
    await acquirePageSlot();

    try {
        const browser = await getBrowser(browserType);

        const defaultOptions = {
            userAgent: browserType === 'firefox' 
