    const seriesObjectRegex = /\{sid:"(s_[a-zA-Z0-9_]+)",[\s\S]*?name:"([^"]+)"[\s\S]*?\}/g;

    let match;
    while ((match = seriesObjectRegex.exec(html)) !== null) {
        const sid = match[1];
        const name = match[2];

        if (seenIds.has(sid)) continue;
        seenIds.add(sid);

        const objStr = match[0];

        // Extract cover
        const thumbMatch = objStr.match(/thumb:\{url:"([^"]+)"/);
        let cover = thumbMatch ? thumbMatch[1] : null;
        if (cover) {
            cover = cover.replace(/\\u002F/g, '/');
        } else {
             const posterMatch = objStr.match(/poster:\{url:"([^"]+)"/);
             if (posterMatch) cover = posterMatch[1].replace(/\\u002F/g, '/');
        }

        const scoreMatch = objStr.match(/score:([0-9.]+)/);
        const score = scoreMatch ? scoreMatch[1] : null;

        const introMatch = objStr.match(/intro:"([^"]+)"/);
        const intro = introMatch ? introMatch[1] : null;

        dramas.push({ sid, name, cover, score, intro });
    }
    return dramas;
}

async function main() {
    let library = [];
    const seenSids = new Set();

    // 1. Scrape Home first to get Hero data
    const homeHtml = fetchWithCurl('https://www.hitv.vip/');
    if (homeHtml) {
        const homeDramas = parseDramasFromHtml(homeHtml);
        console.log(`[Home] Found ${homeDramas.length} dramas.`);

        // Assume first 5 are "Hero" / Featured
        const hero = homeDramas.slice(0, 10);
        fs.writeFileSync('hitv_home_hero.json', JSON.stringify(hero, null, 2));

        homeDramas.forEach(d => {
            if (!seenSids.has(d.sid)) {
                seenSids.add(d.sid);
                library.push(d);
            }
        });
    }

    // 2. Scrape Albums
    for (const album of ALBUMS) {
        const url = `https://www.hitv.vip/share/album/${album.id}`;
        const html = fetchWithCurl(url);
        if (html) {
            const dramas = parseDramasFromHtml(html);
            console.log(`[${album.name}] Found ${dramas.length} dramas.`);

            dramas.forEach(d => {
                if (!seenSids.has(d.sid)) {
                    seenSids.add(d.sid);
                    // Tag it with category if possible (heuristic)
                    d.category = album.name; 
                    library.push(d);
                }
            });
        }
    }

    console.log(`Total unique dramas: ${library.length}`);
    fs.writeFileSync('hitv_library.json', JSON.stringify(library, null, 2));
}

main();

