        console.log('Launching browser to fetch gallery...');
        page = await getNewPage({
            userAgent: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
        });

        console.log('Navigating to https://home.hitv.vip/gallery');
        await page.goto('https://home.hitv.vip/gallery', { waitUntil: 'domcontentloaded', timeout: 30000 });

        const title = await page.title();
        console.log(`Page Title: ${title}`);

        // Wait a bit for content to load
        await page.waitForTimeout(5000);

        const content = await page.content();

        if (content.includes('Server error') || content.includes('error-403')) {
            console.log('Still hitting error page.');
        } else {
            console.log('Page loaded successfully!');
            // Try to find some data
            const items = await page.evaluate(() => {
                // Heuristic: finding items with images or titles
                const elements = document.querySelectorAll('.item, .card, .poster'); // Generic selectors
                return elements.length;
            });
            console.log(`Found ${items} potential items.`);

            // Dump partial content to check structure
            console.log('Content snippet:', content.substring(0, 500));
        }

    } catch (e) {
        console.error('Browser fetch error:', e.message);
    } finally {
        if (page) await page.close();
        await closeBrowser();
    }
}

