async function getHiTvDetail(id) {
    // If ID is not numeric, we need to resolve it
    if (!/^\d+$/.test(id)) {
        console.log(`[HiTV] Resolving Web ID: ${id}`);
        let title = null;

        // 1. Try cache
        if (libraryCache) {
            const item = libraryCache.find(i => i.id === id);
            if (item) title = item.title;
        }

        // 2. Scrape Web Page if cache missed
        if (!title) {
            const html = fetchWithCurl(`https://home.hitv.vip/series/${id}/1`);
            if (html) {
                const titleMatch = html.match(/<title>(.*?)<\/title>/);
                if (titleMatch) {
                    let rawTitle = titleMatch[1];
                    // Clean title: "Name(Ep.1-12)..." -> "Name"
                    // Remove (Ep...), -Ep..., -English..., -Korean...
                    rawTitle = rawTitle.split('(Ep')[0].split('-Ep')[0].split(' - ')[0];
                    title = rawTitle.trim();
                }
            }
        }

        if (title) {
            console.log(`[HiTV] Resolved title: "${title}". Searching...`);
            const searchRes = await searchHiTv(title);
            if (searchRes.items && searchRes.items.length > 0) {
                // Use the first result's ID
                // Ideally we check for exact match, but first result is usually correct
                const numericId = searchRes.items[0].id;
                console.log(`[HiTV] Mapped ${id} -> ${numericId}`);
                // Recursive call with numeric ID
                return getHiTvDetail(numericId);
            }
        }

        console.warn(`[HiTV] Could not resolve Web ID ${id}`);
        return { id, title: title || "Unknown", episodes: [] };
    }

    // Original numeric logic
    const url = `${BASE_URL}/detail?subjectId=${id}&lang=en`;

    try {
        const response = await axios.get(url, { headers: DEFAULT_HEADERS });
        if (response.data && response.data.code === 0 && response.data.data && response.data.data.subject) {
            const d = response.data.data.subject;
            return {
                id: d.subjectId,
                title: d.title,
                description: d.description,
                cover: d.cover ? d.cover.url : null,
                detailPath: d.detailPath,
                episodes: (response.data.data.resource?.seasons || []).flatMap(s => {
                    // Generate episodes based on maxEp if specific list is missing
                    const eps = [];
                    const max = s.maxEp || 0;
                    for (let i = 1; i <= max; i++) {
                        eps.push({
                            number: i,
                            title: `Episode ${i}`,
                            id: `${d.subjectId}-${i}` // Dummy ID as HiTV doesn't expose unique EP IDs in this view usually
                        });
                    }
                    return eps;
                })
            };
        }
        return null;
    } catch (error) {
        console.error(`[HiTV] Detail error for ${id}:`, error.message);
        if (error.response) {
             console.error(`[HiTV] Detail Response: ${error.response.status}`, JSON.stringify(error.response.data));
        }
        return { id, title: "Unknown", episodes: [] };
    }
}

