// In-memory cache for Library
let libraryCache = null;
let lastLibraryFetch = 0;
const CACHE_TTL = 3600 * 1000; // 1 hour

async function getLibrary() {
    if (libraryCache && (Date.now() - lastLibraryFetch < CACHE_TTL)) {
        return libraryCache;
    }

    console.log('[HiTV] Building massive library from API...');

    const categories = ["Drama", "Movie"];
    const countries = ["Korea", "China", "Thailand", "Japan"];
    const pagesToFetch = 3; // Fetch 3 pages per combo -> 2*4*3 = 24 requests * 24 items = ~576 items base

    const tasks = [];

    for (const cat of categories) {
        for (const country of countries) {
            for (let p = 1; p <= pagesToFetch; p++) {
                // browseHiTv(page, pageSize, country, category, genre, sort)
                tasks.push(browseHiTv(p, 24, country, cat, "All", "Hottest")
                    .catch(e => ({ items: [] })) // specific catch to prevent one fail ruining all
                );
            }
        }
    }

    // Also fetch some "Newest" to keep it fresh
    tasks.push(browseHiTv(1, 24, "Korea", "Drama", "All", "Newest"));
    tasks.push(browseHiTv(1, 24, "China", "Drama", "All", "Newest"));

    try {
        const results = await Promise.all(tasks);

        const uniqueItems = new Map();
        results.forEach(res => {
            if (res && res.items) {
                res.items.forEach(item => {
                    // Normalize item structure if needed (browseHiTv returns standard structure)
                    if (!uniqueItems.has(item.id)) {
                        uniqueItems.set(item.id, item);
                    }
                });
            }
        });

        const library = Array.from(uniqueItems.values());
        console.log(`[HiTV] Library built with ${library.length} unique titles.`);

        if (library.length > 0) {
            libraryCache = library;
            lastLibraryFetch = Date.now();
            return library;
        }
    } catch (e) {
        console.error(`[HiTV] Library build failed: ${e.message}`);
    }

    return libraryCache || [];
}

async function getHero() {
    // Get distinct high-rated or popular items for hero
    // We can just grab the first page of "Hottest" Korea Dramas which is usually good
    const res = await browseHiTv(1, 10, "Korea", "Drama", "All", "Recommend");
    return res.items || [];
}

const HITV_COUNTRIES = ["Korea", "China", "Thailand", "Japan", "Vietnam", "Others"];

