// In-memory cache for Library
let libraryCache = null;
let lastLibraryFetch = 0;
const CACHE_TTL = 3600 * 1000; // 1 hour

function fetchWithCurl(url) {
    try {
        const cmd = `curl -s -L -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36" "${url}"`;
        // Increase buffer for large pages
        const output = execSync(cmd, { encoding: 'utf8', maxBuffer: 10 * 1024 * 1024 }); 
        return output;
    } catch (e) {
        console.error(`[HiTV] Curl failed: ${e.message}`);
        return null;
    }
}

function parseDramasFromHtml(html) {
    const dramas = [];
    const seenIds = new Set();

    // Pattern: {sid:"s_...", ... name:"..."}
    const seriesObjectRegex = /\{sid:"(s_[a-zA-Z0-9_]+)",[\s\S]*?name:"([^"]+)"[\s\S]*?\}/g;

    let match;
    while ((match = seriesObjectRegex.exec(html)) !== null) {
        const sid = match[1];
        const name = match[2];

        if (seenIds.has(sid)) continue;
        seenIds.add(sid);

        const objStr = match[0];

        // Extract cover
        const thumbMatch = objStr.match(/thumb:\{url:"([^"]+)"/);
        let cover = thumbMatch ? thumbMatch[1] : null;
        if (cover) {
            cover = cover.replace(/\\u002F/g, '/');
        } else {
             const posterMatch = objStr.match(/poster:\{url:"([^"]+)"/);
             if (posterMatch) cover = posterMatch[1].replace(/\\u002F/g, '/');
        }

        const scoreMatch = objStr.match(/score:([0-9.]+)/);
        const score = scoreMatch ? scoreMatch[1] : null;

        dramas.push({ id: sid, title: name, cover, rating: score });
    }
    return dramas;
}

async function getLibrary() {
    if (libraryCache && (Date.now() - lastLibraryFetch < CACHE_TTL)) {
        return libraryCache;
    }

    console.log('[HiTV] Refreshing library from home page...');
    const html = fetchWithCurl('https://www.hitv.vip/');
    if (html) {
        const items = parseDramasFromHtml(html);
        if (items.length > 0) {
            libraryCache = items;
            lastLibraryFetch = Date.now();
            return items;
        }
    }

    // Return stale cache if fetch fails, or empty array
    return libraryCache || [];
}

async function getHero() {
    const lib = await getLibrary();
    return lib.slice(0, 10);
}

const HITV_COUNTRIES = ["Korea", "China", "Thailand", "Japan", "Vietnam", "Others"];

