// In-memory cache for Library
let libraryCache = null;
let lastLibraryFetch = 0;
const CACHE_TTL = 12 * 3600 * 1000; // 12 hours

// Concurrency helper
async function runBatch(tasks, limit) {
    const results = [];
    for (let i = 0; i < tasks.length; i += limit) {
        const batch = tasks.slice(i, i + limit);
        const batchResults = await Promise.all(batch.map(fn => fn()));
        results.push(...batchResults);
    }
    return results;
}

async function getLibrary() {
    if (libraryCache && (Date.now() - lastLibraryFetch < CACHE_TTL)) {
        return libraryCache;
    }

    console.log('[HiTV] Building MASSIVE library (this may take a moment)...');

    const categories = ["Drama", "Movie", "Variety"];
    const countries = ["Korea", "China", "Thailand", "Japan", "Vietnam", "Others"];
    const sorts = ["Hottest", "Newest"];
    const maxPage = 5; 

    const taskFactories = [];

    // Create task factories (functions that return promises) to avoid starting all at once
    for (const cat of categories) {
        for (const country of countries) {
            for (const sort of sorts) {
                for (let p = 1; p <= maxPage; p++) {
