const axios = require('axios');
const { execSync } = require('child_process');

const BASE_URL = 'https://h5-api.aoneroom.com/wefeed-h5api-bff';
const DEFAULT_HEADERS = {
    'Content-Type': 'application/json',
    'User-Agent': 'Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/114.0.0.0 Mobile Safari/537.36',
    'Origin': 'https://www.gohitv.com',
    'Referer': 'https://www.gohitv.com/'
};

const fs = require('fs').promises;
const path = require('path');

// In-memory cache for Library
let libraryCache = [];
let lastLibraryFetch = 0;
let isBuilding = false;
const CACHE_TTL = 12 * 3600 * 1000; // 12 hours
const CACHE_FILE = path.join(__dirname, '../hitv_library_cache.json');

// Load cache from disk on startup
(async () => {
    try {
        const data = await fs.readFile(CACHE_FILE, 'utf8');
        libraryCache = JSON.parse(data);
        lastLibraryFetch = Date.now(); // Assume fresh on restart or file mod time
        console.log(`[HiTV] Loaded ${libraryCache.length} items from disk cache.`);
    } catch (e) {
        console.log('[HiTV] No disk cache found, library empty.');
    }
})();

const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

async function fetchWithRetry(fn, retries = 3, delay = 1000) {
    try {
        return await fn();
    } catch (e) {
        if (retries > 0) {
            await sleep(delay);
            return fetchWithRetry(fn, retries - 1, delay * 2);
        }
        return { items: [] }; 
    }
}

async function runBatch(tasks, limit, delayMs = 1500) {
    const results = [];
    for (let i = 0; i < tasks.length; i += limit) {
        const batch = tasks.slice(i, i + limit);
        const batchResults = await Promise.all(batch.map(fn => fn()));
        results.push(...batchResults);
        if (i + limit < tasks.length) {
            await sleep(delayMs);
        }
    }
    return results;
}

async function buildLibrary() {
    if (isBuilding) return;
    isBuilding = true;
    console.log('[HiTV] Starting background library build...');

    const categories = ["Drama", "Movie", "Variety"];
    const countries = ["Korea", "China", "Thailand", "Japan", "Vietnam", "Others"];
    const sorts = ["Hottest", "Newest"];
    const maxPage = 10; 

    const taskFactories = [];

    for (const cat of categories) {
        for (const country of countries) {
            for (const sort of sorts) {
                for (let p = 1; p <= maxPage; p++) {
                    taskFactories.push(() => 
                        fetchWithRetry(() => browseHiTv(p, 24, country, cat, "All", sort))
                    );
                }
            }
        }
    }

    console.log(`[HiTV] Queued ${taskFactories.length} requests.`);

    try {
        // Concurrency 2, Delay 2s = ~30 requests/min
        // 360 requests => ~12 minutes
        const allItemsNested = await runBatch(taskFactories, 2, 2000);

        const uniqueItems = new Map();

        // Merge with existing cache to preserve items if API fails/partial
        libraryCache.forEach(item => uniqueItems.set(item.id, item));

        allItemsNested.forEach(res => {
            if (res && res.items) {
                res.items.forEach(item => {
                    uniqueItems.set(item.id, item);
                });
            }
        });

        const library = Array.from(uniqueItems.values());
        library.sort((a, b) => (b.releaseDate || "").localeCompare(a.releaseDate || ""));

        console.log(`[HiTV] Library build complete. Total Unique: ${library.length}`);

        if (library.length > 0) {
            libraryCache = library;
            lastLibraryFetch = Date.now();
            await fs.writeFile(CACHE_FILE, JSON.stringify(library));
        }
    } catch (e) {
        console.error(`[HiTV] Library build failed: ${e.message}`);
    } finally {
        isBuilding = false;
    }
}

async function getLibrary() {
    // If cache is empty or stale, trigger build
    if (libraryCache.length === 0 || (Date.now() - lastLibraryFetch > CACHE_TTL)) {
        // Trigger background build (don't await)
        buildLibrary();
    }

    // Return what we have immediately
    return libraryCache;
}

async function getHero() {
    const res = await browseHiTv(1, 10, "Korea", "Drama", "All", "Recommend");
    return res.items || [];
}

async function getHero() {
    // Get distinct high-rated or popular items for hero
    // We can just grab the first page of "Hottest" Korea Dramas which is usually good
    const res = await browseHiTv(1, 10, "Korea", "Drama", "All", "Recommend");
    return res.items || [];
}

const HITV_COUNTRIES = ["Korea", "China", "Thailand", "Japan", "Vietnam", "Others"];
const HITV_CATEGORIES = [
    { name: "Drama", id: 2 },
    { name: "Movie", id: 1 },
    { name: "Variety", id: 3 }
];
const HITV_GENRES = [
    "All", "Romance", "Comedy", "Action", "Thriller", "Horror", "Crime", "Mystery", 
    "Fantasy", "Family", "History", "Youth", "Medical", "Law", "Wuxia", "Xianxia"
];
const HITV_SORTS = ["Hottest", "Newest", "Latest", "Recommend", "General"];

async function browseHiTv(page = 1, pageSize = 20, country = "Korea", category = "Drama", genre = "All", sort = "Hottest") {
    const url = `${BASE_URL}/subject/filter`;

    // Resolve category name to ID
    const catObj = HITV_CATEGORIES.find(c => c.name.toLowerCase() === category.toLowerCase()) || HITV_CATEGORIES[0];

    const payload = {
        page: parseInt(page),
        perPage: parseInt(pageSize),
        channelId: catObj.id, 
        country: country,
        sort: sort
    };

    // Add genre if specified and not "All"
    if (genre && genre.toLowerCase() !== "all") {
        payload.genre = genre;
    }

    try {
        const response = await axios.post(url, payload, { headers: DEFAULT_HEADERS });
        if (response.data && response.data.code === 0 && response.data.data) {
            return {
                page: response.data.data.pager.page,
                hasNext: response.data.data.pager.hasMore,
                items: response.data.data.items.map(item => ({
                    id: item.subjectId,
                    title: item.title,
                    cover: item.cover ? item.cover.url : null,
                    rating: item.imdbRatingValue,
                    releaseDate: item.releaseDate,
                    genre: item.genre
                }))
            };
        }
        return { items: [] };
    } catch (error) {
        console.error('[HiTV] Browse error:', error.message);
        return { items: [] };
    }
}

function getHiTvCountries() {
    return HITV_COUNTRIES;
}

function getHiTvCategories() {
    return HITV_CATEGORIES.map(c => c.name);
}

function getHiTvGenres() {
    return HITV_GENRES;
}

function getHiTvSorts() {
    return HITV_SORTS;
}

async function getHiTvDetail(id) {
    // If ID is not numeric, we need to resolve it
    if (!/^\d+$/.test(id)) {
        console.log(`[HiTV] Resolving Web ID: ${id}`);
        let title = null;

        // 1. Try cache
        if (libraryCache) {
            const item = libraryCache.find(i => i.id === id);
            if (item) title = item.title;
        }

        // 2. Scrape Web Page if cache missed
        if (!title) {
            const html = fetchWithCurl(`https://home.hitv.vip/series/${id}/1`);
            if (html) {
                const titleMatch = html.match(/<title>(.*?)<\/title>/);
                if (titleMatch) {
                    let rawTitle = titleMatch[1];
                    // Clean title: "Name(Ep.1-12)..." -> "Name"
                    // Remove (Ep...), -Ep..., -English..., -Korean...
                    rawTitle = rawTitle.split('(Ep')[0].split('-Ep')[0].split(' - ')[0];
                    title = rawTitle.trim();
                }
            }
        }

        if (title) {
            console.log(`[HiTV] Resolved title: "${title}". Searching...`);
            const searchRes = await searchHiTv(title);
            if (searchRes.items && searchRes.items.length > 0) {
                // Use the first result's ID
                // Ideally we check for exact match, but first result is usually correct
                const numericId = searchRes.items[0].id;
                console.log(`[HiTV] Mapped ${id} -> ${numericId}`);
                // Recursive call with numeric ID
                return getHiTvDetail(numericId);
            }
        }

        console.warn(`[HiTV] Could not resolve Web ID ${id}`);
        return { id, title: title || "Unknown", episodes: [] };
    }

    // Original numeric logic
    const url = `${BASE_URL}/detail?subjectId=${id}&lang=en`;

    try {
        const response = await axios.get(url, { headers: DEFAULT_HEADERS });
        if (response.data && response.data.code === 0 && response.data.data && response.data.data.subject) {
            const d = response.data.data.subject;
            return {
                id: d.subjectId,
                title: d.title,
                description: d.description,
                cover: d.cover ? d.cover.url : null,
                detailPath: d.detailPath,
                episodes: (response.data.data.resource?.seasons || []).flatMap(s => {
                    // Generate episodes based on maxEp if specific list is missing
                    const eps = [];
                    const max = s.maxEp || 0;
                    for (let i = 1; i <= max; i++) {
                        eps.push({
                            number: i,
                            title: `Episode ${i}`,
                            id: `${d.subjectId}-${i}` // Dummy ID as HiTV doesn't expose unique EP IDs in this view usually
                        });
                    }
                    return eps;
                })
            };
        }
        return null;
    } catch (error) {
        console.error(`[HiTV] Detail error for ${id}:`, error.message);
        if (error.response) {
             console.error(`[HiTV] Detail Response: ${error.response.status}`, JSON.stringify(error.response.data));
        }
        return { id, title: "Unknown", episodes: [] };
    }
}

async function searchHiTv(query, type = 2, page = 1) {
    const url = `${BASE_URL}/subject/search`;
    const payload = {
        keyword: query,
        page: parseInt(page),
        perPage: 24,
        subjectType: type // 1 for Movies, 2 for Series
    };

    try {
        const response = await axios.post(url, payload, { headers: DEFAULT_HEADERS });
        if (response.data && response.data.code === 0 && response.data.data) {
             const list = response.data.data.items || [];
             return {
                page: response.data.data.pager ? response.data.data.pager.page : page,
                hasNext: response.data.data.pager ? response.data.data.pager.hasMore : false,
                items: list.map(item => ({
                    id: item.subjectId,
                    title: item.title,
                    cover: item.cover ? item.cover.url : null,
                    rating: item.imdbRatingValue,
                    releaseDate: item.releaseDate,
                    genre: item.genre,
                    type: item.subjectType === 1 ? "movie" : "tv"
                }))
            };
        }
        return { items: [], page, hasNext: false };
    } catch (error) {
        console.error('[HiTV] Search error:', error.message);
        return { items: [], page, hasNext: false };
    }
}

module.exports = { browseHiTv, searchHiTv, getHiTvDetail, getHiTvCountries, getHiTvCategories, getHiTvGenres, getHiTvSorts, getLibrary, getHero };

