    "Turkey", "Vietnam", "Others"
];

const HITV_CATEGORIES = [
    { name: "Drama", id: 2 },
    { name: "Movie", id: 1 },
    { name: "Variety", id: 3 },
    { name: "Anime", id: 4 } // Assuming Anime might exist or mapped
];

const HITV_GENRES = [
    "All", "Action", "Adventure", "Animation", "Biography", "Comedy", "Crime", 
    "Documentary", "Drama", "Family", "Fantasy", "Film-Noir", "Game-Show", "History", 
    "Horror", "Music", "Musical", "Mystery", "News", "Reality-TV", "Romance", 
    "Sci-Fi", "Short", "Sport", "Talk-Show", "Thriller", "War", "Western", "Wuxia", "Xianxia"
];

const HITV_SORTS = ["ForYou", "Hottest", "Newest", "Latest", "Recommend", "General"];

async function browseHiTv(page = 1, pageSize = 20, country = "Korea", category = "Drama", genre = "All", sort = "Hottest", year = null) {
    const url = `${BASE_URL}/subject/filter`;

    const catObj = HITV_CATEGORIES.find(c => c.name.toLowerCase() === category.toLowerCase()) || HITV_CATEGORIES[0];

    const payload = {
        page: parseInt(page),
        perPage: parseInt(pageSize),
        channelId: catObj.id, 
        country: country === "All" ? undefined : country, // API likely omits for All
        sort: sort
    };

    if (genre && genre.toLowerCase() !== "all") {
        payload.genre = genre;
    }

    if (year) {
        payload.year = year.toString();
    }

    try {
        const response = await axios.post(url, payload, { headers: DEFAULT_HEADERS });
        if (response.data && response.data.code === 0 && response.data.data) {
            return {
                page: response.data.data.pager.page,
                hasNext: response.data.data.pager.hasMore,
                items: response.data.data.items.map(item => ({
                    id: item.subjectId,
                    title: item.title,
                    cover: item.cover ? item.cover.url : null,
                    rating: item.imdbRatingValue,
                    releaseDate: item.releaseDate,
                    genre: item.genre,
                    year: item.releaseDate ? item.releaseDate.split('-')[0] : null
                }))
            };
        }
        return { items: [] };
    } catch (error) {
        console.error('[HiTV] Browse error:', error.message);
        return { items: [] };
    }
}

async function browseSflixDrama({ page = 1, country = "Korea", genre = "All", sort = "Hottest", year = null }) {
    console.log(`[Sflix] Browsing Drama: Page ${page}, ${country}, ${genre}, ${sort}, ${year || 'All Years'}`);

    // 1. Fetch from HiTV API
    const res = await browseHiTv(page, 28, country, "Drama", genre, sort, year);
    if (!res.items || res.items.length === 0) return res;

    // 2. Enrich with TMDB Backdrops
    const enrichedItems = await Promise.all(res.items.map(async (item) => {
        try {
            // Only search if we have a title and it's not enriched yet
            if (item.title) {
                // Search specifically for TV since we are in Drama mode
                const results = await tmdb.search(item.title, 'tv', item.year);
                if (results && results.length > 0) {
                    const match = results[0];
                    if (match.backdrop_path) {
                        item.backdrop = `https://image.tmdb.org/t/p/original${match.backdrop_path}`;
                    }
                    if (match.poster_path && !item.cover) { // Fallback if HiTV cover missing
                        item.cover = `https://image.tmdb.org/t/p/w780${match.poster_path}`;
                    }
                    item.tmdbId = match.id;
                    item.overview = match.overview;
                }
            }
        } catch (e) {
            // Ignore enrichment errors, return original item
        }
        return item;
    }));

    return { ...res, items: enrichedItems };
}

