function fetchWithCurl(url) {
    try {
        const cmd = `curl -s -L -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" "${url}"`;
        const output = execSync(cmd, { encoding: 'utf8', maxBuffer: 10 * 1024 * 1024 }); 
        return output;
    } catch (e) {
        return null;
    }
}

