                } else if (match.poster_path) {
                    item.cover = `https://image.tmdb.org/t/p/w780${match.poster_path}`;
                }
                if (match.overview) item.description = match.overview;
                if (match.vote_average) item.rating = match.vote_average.toString();
            } else {
