async function browseHiTv(page = 1, pageSize = 20, country = "Korea", category = "Drama", genre = "All", sort = "Hottest", year = null) {
    const url = `${BASE_URL}/subject/filter`;

    const catObj = HITV_CATEGORIES.find(c => c.name.toLowerCase() === category.toLowerCase()) || HITV_CATEGORIES[0];

    const payload = {
        page: parseInt(page),
        perPage: parseInt(pageSize),
        channelId: catObj.id, 
        country: country === "All" ? undefined : country, 
        sort: sort
    };

