            'latest': 'Newest',
            'hottest': 'Hottest',
            'foryou': 'ForYou',
            'trending': 'Recommend',
            'popular': 'Hottest'
        };

        const params = {
            page: page,
            country: country || "All",
            sort: sortMap[sort?.toLowerCase()] || sort || "ForYou",
            genre: genre || "All",
            year: req.query.year || null
        };

        const data = await hitvApi.browseDrama(params);
        res.json({ success: true, ...data });
